let type = 'novel'
if (key.startsWith('c') || key.startsWith('C')) {
  type = 'comic'
  key = key.slice(1)
} else if (key.startsWith('a') || key.startsWith('A')) {
  type = 'audio'
  key = key.slice(1)
} else if (key.startsWith('v') || key.startsWith('V')) {
  type = 'video'
  key = key.slice(1)
}
getApiUrl(`/${type}/search`, { keyword: key, page, size: 20, order_type: String(source.get('order')) || 0 })
